            Some(n) => &source[n.start_byte()..n.end_byte()],
            None => return,
        };

        // Match the exact flipud/fliplr pair, each with exactly one argument
        let is_pair = match func_name {
            "flipud" => inner_name == "fliplr",
            "fliplr" => inner_name == "flipud",
            _ => false,
